// src/screens/TreatmentPlanScreen.js
import { useState, useEffect } from 'react';
import { View, Text, StyleSheet, ScrollView, TouchableOpacity, Alert } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { colors, severityColor } from '../theme/colors';
import { useLanguage } from '../context/LanguageContext';
import { getDiseaseProfile } from '../utils/diseaseCatalog';
import { addReminder, hasActiveReminder } from '../utils/reminderStorage';

const REMINDER_DAYS_AHEAD = 3;

export default function TreatmentPlanScreen({ route, navigation }) {
  const { t } = useLanguage();

  const diseaseId = route?.params?.diseaseId ?? 'leafBlight';
  const damagePercent = route?.params?.damagePercent ?? 0;

  const profile = getDiseaseProfile(diseaseId);
  const diseaseName = t(profile.nameKey);
  const actions = profile.mitigationKeys.map((key) => t(key));

  const [scheduling, setScheduling] = useState(false);
  const [reminderSet, setReminderSet] = useState(false);

  useEffect(() => {
    hasActiveReminder(diseaseId, 'Crop').then(setReminderSet);
  }, [diseaseId]);

  const ORGANICS = [
    { name: t('organicBakingSodaName'), desc: t('organicBakingSodaDesc') },
    { name: t('organicNeemName'), desc: t('organicNeemDesc') },
  ];

  async function handleScheduleReminder() {
    if (reminderSet) {
      Alert.alert(t('reminderAlreadySet'), t('reminderAlreadySetDesc'));
      return;
    }

    setScheduling(true);
    try {
      const reminder = await addReminder({
        diseaseId,
        diseaseName,
        cropLabel: 'Crop',
        daysAhead: REMINDER_DAYS_AHEAD,
      });
      setReminderSet(true);

      const dueDate = new Date(reminder.dueDateISO);
      Alert.alert(
        t('reminderScheduledTitle'),
        `${t('reminderScheduledDesc')}\n\n${dueDate.toLocaleDateString()}`
      );
    } catch (e) {
      console.warn('Reminder scheduling error:', e);
      Alert.alert(t('reminderErrorTitle'), e.message ?? t('reminderErrorDesc'));
    } finally {
      setScheduling(false);
    }
  }

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <TouchableOpacity onPress={() => navigation.goBack()}>
          <Ionicons name="chevron-back" size={24} color={colors.white} />
        </TouchableOpacity>
        <Text style={styles.headerTitle}>{t('treatmentPlan')}</Text>
        <View style={{ width: 48 }} />
      </View>

      <ScrollView contentContainerStyle={styles.body}>
        <View style={styles.diseaseCard}>
          <View style={styles.diseaseIconWrap}>
            <Ionicons name="leaf" size={22} color={colors.warning} />
          </View>
          <View>
            <Text style={styles.diseaseName}>{diseaseName}</Text>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 5, marginTop: 2 }}>
              <View style={[styles.severityDot, { backgroundColor: severityColor('moderate') }]} />
              <Text style={styles.severityText}>{damagePercent.toFixed(1)}% {t('leafTissueDamage')}</Text>
            </View>
          </View>
        </View>

        {diseaseId === 'healthy' ? (
          <View style={styles.card}>
            {actions.map((action, i) => (
              <View key={i} style={styles.actionRow}>
                <Ionicons name="checkmark-circle" size={18} color={colors.ok} />
                <Text style={styles.actionText}>{action}</Text>
              </View>
            ))}
          </View>
        ) : (
          <>
            <Text style={styles.sectionTitle}>{t('recommendedActions')}</Text>
            <View style={styles.card}>
              {actions.map((action, i) => (
                <View key={i} style={styles.actionRow}>
                  <Ionicons name="checkmark-circle" size={18} color={colors.ok} />
                  <Text style={styles.actionText}>{action}</Text>
                </View>
              ))}
            </View>

            <Text style={styles.sectionTitle}>{t('organicAlternatives')}</Text>
            <View style={styles.card}>
              {ORGANICS.map((item, i) => (
                <View key={i} style={i > 0 ? { marginTop: 16 } : undefined}>
                  <Text style={styles.organicName}>{item.name}</Text>
                  <Text style={styles.organicDesc}>{item.desc}</Text>
                </View>
              ))}
            </View>

            <TouchableOpacity
              style={[styles.reminderBtn, reminderSet && styles.reminderBtnDone]}
              activeOpacity={0.85}
              onPress={handleScheduleReminder}
              disabled={scheduling}
            >
              <Text style={styles.reminderBtnText}>
                {scheduling
                  ? t('schedulingReminder')
                  : reminderSet
                  ? `✓ ${t('reminderAlreadySet')}`
                  : t('scheduleReminder')}
              </Text>
            </TouchableOpacity>
          </>
        )}
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: colors.background },
  header: {
    backgroundColor: colors.primaryDark,
    paddingTop: 54,
    paddingBottom: 16,
    paddingHorizontal: 20,
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  headerTitle: { color: colors.white, fontSize: 18, fontWeight: '800' },
  body: { padding: 20, paddingBottom: 40 },
  diseaseCard: {
    backgroundColor: colors.card,
    borderRadius: 14,
    padding: 16,
    flexDirection: 'row',
    alignItems: 'center',
    gap: 14,
    marginBottom: 20,
  },
  diseaseIconWrap: {
    width: 44,
    height: 44,
    borderRadius: 12,
    backgroundColor: colors.warningBg,
    alignItems: 'center',
    justifyContent: 'center',
  },
  diseaseName: { fontWeight: '800', fontSize: 16, color: colors.textDark },
  severityDot: { width: 8, height: 8, borderRadius: 4 },
  severityText: { fontSize: 12, color: colors.textMuted },
  sectionTitle: { fontWeight: '800', fontSize: 15, color: colors.textDark, marginBottom: 10 },
  card: { backgroundColor: colors.card, borderRadius: 14, padding: 16, marginBottom: 20 },
  actionRow: { flexDirection: 'row', alignItems: 'flex-start', gap: 10, marginBottom: 12 },
  actionText: { flex: 1, fontSize: 13, color: colors.textDark, lineHeight: 18 },
  organicName: { fontWeight: '700', color: colors.primary, fontSize: 14, marginBottom: 4 },
  organicDesc: { fontSize: 13, color: colors.textMuted, lineHeight: 18 },
  reminderBtn: { backgroundColor: colors.leafGreen, borderRadius: 12, paddingVertical: 15, alignItems: 'center' },
  reminderBtnDone: { backgroundColor: colors.textMuted },
  reminderBtnText: { color: colors.white, fontWeight: '800', fontSize: 15 },
});